// Execution order for jobs that depend on other jobs ("run after").

export interface PlannedJob {
  id: string;
  dependsOn: readonly string[];
}

export class DependencyError extends Error {
  ids: string[];

  constructor(message: string, ids: string[]) {
    super(message);
    this.name = "DependencyError";
    this.ids = ids;
  }
}

// Job ids in an order where every job comes after all of its dependencies.
//
// The order is stable: whenever several jobs are ready to run, the one listed first in
// `jobs` goes first. Throws DependencyError for duplicate ids, for dependencies on
// unknown jobs, and for cycles (ids: the jobs that could not be scheduled, in input order).
export function executionOrder(jobs: readonly PlannedJob[]): string[] {
  const ids = new Set<string>();
  for (const job of jobs) {
    if (ids.has(job.id)) throw new DependencyError(`duplicate job id ${job.id}`, [job.id]);
    ids.add(job.id);
  }
  for (const job of jobs) {
    const missing = job.dependsOn.filter((dep) => !ids.has(dep));
    if (missing.length > 0) {
      throw new DependencyError(`job ${job.id} depends on unknown job(s) ${missing.join(", ")}`, [job.id]);
    }
  }

  const done = new Set<string>();
  const remaining = [...jobs];
  const order: string[] = [];
  while (remaining.length > 0) {
    const index = remaining.findIndex((job) => job.dependsOn.every((dep) => done.has(dep)));
    if (index < 0) {
      const stuck = remaining.map((job) => job.id);
      throw new DependencyError(`dependency cycle among ${stuck.join(", ")}`, stuck);
    }
    const [job] = remaining.splice(index, 1);
    done.add(job.id);
    order.push(job.id);
  }
  return order;
}

