// Min-heap of input positions: the ready job listed first always comes out first.
class PositionHeap {
  items: number[];

  constructor() {
    this.items = [];
  }

  get size(): number {
    return this.items.length;
  }

  push(value: number): void {
    const items = this.items;
    items.push(value);
    let i = items.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (items[parent] <= items[i]) break;
      [items[parent], items[i]] = [items[i], items[parent]];
      i = parent;
    }
  }

  pop(): number {
    const items = this.items;
    const top = items[0];
    const last = items.pop() as number;
    if (items.length > 0) {
      items[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < items.length && items[left] < items[smallest]) smallest = left;
        if (right < items.length && items[right] < items[smallest]) smallest = right;
        if (smallest === i) break;
        [items[smallest], items[i]] = [items[i], items[smallest]];
        i = smallest;
      }
    }
    return top;
  }
}

// Job ids in an order where every job comes after all of its dependencies.
//
// The order is stable: whenever several jobs are ready to run, the one listed first in
// `jobs` goes first. Throws DependencyError for duplicate ids, for dependencies on
// unknown jobs, and for cycles (ids: the jobs that could not be scheduled, in input order).
export function executionOrder(jobs: readonly PlannedJob[]): string[] {
  const position = new Map<string, number>();
  jobs.forEach((job, i) => {
    if (position.has(job.id)) throw new DependencyError(`duplicate job id ${job.id}`, [job.id]);
    position.set(job.id, i);
  });

  const waitingOn = new Array<number>(jobs.length).fill(0);
  const dependents: number[][] = jobs.map(() => []);
  jobs.forEach((job, i) => {
    const deps = job.dependsOn;
    const missing = deps.filter((dep) => !position.has(dep));
    if (missing.length > 0) {
      throw new DependencyError(`job ${job.id} depends on unknown job(s) ${missing.join(", ")}`, [job.id]);
    }
    for (const dep of deps) {
      dependents[position.get(dep) as number].push(i);
      waitingOn[i] += 1;
    }
  });

  const ready = new PositionHeap();
  waitingOn.forEach((count, i) => {
    if (count === 0) ready.push(i);
  });
  const order: string[] = [];
  while (ready.size > 0) {
    const i = ready.pop();
    order.push(jobs[i].id);
    for (const next of dependents[i]) {
      waitingOn[next] -= 1;
      if (waitingOn[next] === 0) ready.push(next);
    }
  }
  if (order.length < jobs.length) {
    const stuck = jobs.filter((_, i) => waitingOn[i] > 0).map((job) => job.id);
    throw new DependencyError(`dependency cycle among ${stuck.join(", ")}`, stuck);
  }
  return order;
}
